// ── Types ──────────────────────────────────────────────────────────────────────

interface ChatMessage {
  role: 'user' | 'assistant' | 'system';
  content: string;
}

interface NavAction {
  action: 'navigate';
  page: string;
  label?: string;
}

interface AttachedFile {
  name: string;
  kind: 'image' | 'text';
  textContent?: string;
  imageDataUrl?: string;
  size: number;
}

interface TaskAction {
  action: 'create_task' | 'create_tasks' | 'suggest_task' | 'edit_task' | 'delete_task';
  title?: string;
  description?: string;
  priority?: 'none' | 'blue' | 'yellow' | 'red';
  due_date?: string;
  due_time?: string;
  tasks?: Array<{ title: string; description?: string; priority?: string; due_date?: string }>;
}

interface ChainStep {
  action: 'page_action' | 'create_task' | 'navigate';
  // page_action
  name?: string;
  args?: any;
  // create_task
  title?: string;
  description?: string;
  priority?: string;
  // navigate
  page?: string;
  label?: string;
}

interface ChainAction {
  action: 'chain';
  plan: string;
  steps: ChainStep[];
}

interface ClarifyAction {
  action: 'clarify';
  question: string;
  field: string;
  options?: string[];
  // pending context — filled before asking
  pendingActionName?: string;
  pendingArgs?: Record<string, any>;
  originalRequest?: string;
}


